    const key=_megaStateKey(b);
    const im=XART.get(key);
    const wmul=(b.art==='bz6')?0.92:1.02;                 // void's crescent wings are widest — pull it in a touch
    const w=b.w*wmul, h=w*(im.naturalHeight/im.naturalWidth);
    const yy=b.y+Math.sin((b.t||0)*1.5)*6; b._drawY=yy; b._drawW=w; b._drawH=h;
    // face the player: the art natively points UP (away) — flip it vertically so the nose points DOWN.
