    const _pips=(cx,lv)=>{ const PW=2.6, GAP=1, tot=5*PW+4*GAP; let x=cx-tot/2; const col=_LVLCOL[clamp(lv,1,5)]||'#ff8a1e';
      for(let i=0;i<5;i++){ g.fillStyle=(i<lv)?col:'#1b2430'; g.fillRect(x,vy,PW,5); x+=PW+GAP; } };
