  const cx=[0.138*VW,0.338*VW,0.526*VW,0.693*VW,0.872*VW], vy=HUDH*0.63;
  g.textBaseline='middle';
  g.save(); g.shadowColor='#ffcf4a'; g.shadowBlur=6; g.fillStyle='#ffe06b'; g.font='bold 15px monospace'; g.textAlign='center';
