  cruc:          {pat:'wall',    every:3},
  miner:         {pat:'wall',    every:4},
  carrier:       {pat:'wall',    every:2},
  crawl:         {pat:'stagger', every:3},
  pod:           {pat:'pincer',  every:3},
  golem:         {alt:['stagger','rake'],    every:3},
  lavamaw:       {pat:'fan',     every:3},
