    const left=OPEN_T[4]-opening.t, seg=(OPEN_T[4]-OPEN_T[3])/4;
    const n=Math.max(0,Math.ceil(left/seg));
    const txt = n>0 ? String(Math.min(3,n)) : 'GO!';
